    groups = defaultdict(list)

    for result in search_results:
        # Get the grouping field value from metadata
        group_value = result.metadata.get(group_by_field, 'unknown')

        # Convert non-string group values to strings for consistent keys
        if not isinstance(group_value, str):
            group_value = str(group_value)

        groups[group_value].append(result)

    # Calculate aggregated statistics for each group
    aggregated_stats = {}

    for group_value, results in groups.items():
        stats = {}

        if aggregation_funcs is None:
            # Default aggregation: count, average score, max score, min score
            scores = [result.score for result in results]

            stats['count'] = len(results)
            stats['avg_score'] = sum(scores) / len(scores) if scores else 0.0
            stats['max_score'] = max(scores) if scores else 0.0
            stats['min_score'] = min(scores) if scores else 0.0
        else:
            # Custom aggregation functions
            for stat_name, func in aggregation_funcs.items():
                try:
                    if stat_name == 'count':
                        # Special handling for count - apply to the list directly
                        stats[stat_name] = func(results)
                    elif stat_name == 'score' or 'score' in stat_name:
                        # Apply function to scores
                        scores = [result.score for result in results]
                        stats[stat_name] = func(scores) if scores else 0.0
                    else:
                        # For other fields, try to extract from metadata or apply to results
                        values = []
                        for result in results:
                            if stat_name in result.metadata:
                                values.append(result.metadata[stat_name])

                        if values:
                            stats[stat_name] = func(values)
                        else:
                            # If no metadata field found, apply to results list
                            stats[stat_name] = func(results)
                except Exception as e:
                    # If aggregation fails, skip this statistic
                    stats[stat_name] = None

        aggregated_stats[group_value] = stats

    return aggregated_stats

